-- Receipts and invoices attached to a transaction.
-- Files live on disk under data/receipts/<workspace>/<transaction>/; file_name is generated by us, never the user's name.
CREATE TABLE transaction_receipts (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  workspace_id INTEGER NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
  transaction_id INTEGER NOT NULL,
  file_name TEXT NOT NULL,
  original_name TEXT NOT NULL,
  mime TEXT NOT NULL,
  size INTEGER NOT NULL,
  uploaded_at TEXT NOT NULL DEFAULT (datetime('now'))
);

CREATE INDEX idx_transaction_receipts_txn ON transaction_receipts(workspace_id, transaction_id);
